import{z as n,x as i,o as r,c as p,q as s,j as l,D as t,d as e,s as B,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"推测执行与恢复","description":"","frontmatter":{"title":"推测执行与恢复","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/speculation-recovery.md","filePath":"cs/speculation-recovery.md","lastUpdated":1791063341000}'),c={name:"cs/speculation-recovery.md"};function d(h,a,D,m,u,F){const o=i("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="推测执行与恢复" tabindex="-1">推测执行与恢复 <a class="header-anchor" href="#推测执行与恢复" aria-label="Permalink to &quot;推测执行与恢复&quot;">​</a></h1><div class="epigraph"><p>按预测把指令送进窗口可以填满功能单元；一旦核对失败，架构寄存器、内存与预测器状态都要回到那个分支之前，像那些指令从未执行。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach；Smith and Pleszkun, Implementing Precise Interrupts, ISCA 1985 整理</footer></div><p><a href="/cs/loop-predictor">上一课</a>要求预测表在提交后才固化。<a href="/cs/ooo-rob">乱序与 ROB</a> 已经规定：执行可以超前，架构状态只在队头提交。<a href="/cs/tomasulo">Tomasulo</a> 用标签唤醒。本课不重画保留站。缺口是：<strong>误预测不是异常，但恢复动作与精确异常同源——检查点、冲刷、从正确 PC 重取。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>深流水 + 宽发射意味着核对点（分支 EX/ALU）与 IF 之间可能已有几十条推测指令：它们改了重命名映射、占了 ROB 项、可能发了 load。若只冲刷流水线寄存器（五级那套），乱序窗口里的副作用还在。缺口不是再训一个预测器，而是<strong>在每个（或足够密的）推测点留下可恢复快照</strong>。</p><p><span class="marginnote">数字实例：深流水宽发射的核在分支核对点前平均压着 30-50 条推测指令。一次误预测不是重填五级流水，而是重填几十项的 ROB 与发射队列——这就是误预测罚金从五级的 1-2 拍涨到 15-20 拍的原因，也是预测准确率值得抠到 99% 的原因。</span></p><p><span class="marginnote">Smith–Pleszkun 的结果移位、未来文件、ROB 三种精确中断实现，乱序核几乎都走 ROB：冲刷头之后的项即丢掉推测写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在预测分支处：复制一份映射表（或用检查点栈 / 带版本号的映射），记下 GHR 与循环器等预测器检查点，ROB 记该分支的序号。核对成功：提交路径上释放检查点。核对失败：</p><ol><li>恢复映射表到该分支；</li><li>作废 ROB 中更年轻的项，释放其物理寄存器与发射队列槽；</li><li>取消未提交的 load/store；</li><li>恢复 GHR 等；</li><li>IF 从正确目标重取。</li></ol><p><span class="marginnote">术语翻译：检查点（checkpoint）就是分支解码时顺手复制的重命名映射表快照。核对失败时不许慢慢重算，而是整表瞬回——平时多占一份表的钱，换冲刷时一个周期的恢复时间。</span></p>',11)),(r(),l(A,null,{default:t(()=>[B(o,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E6%8C%89%E9%A2%84%E6%B5%8B%E5%8F%96%E6%8C%87%E5%B9%B6%E5%88%86%E9%85%8D%20ROB%22%5D%20--%3E%20CHK%5B%22%E5%88%86%E6%94%AF%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%AF%B9%22%7C%20KEEP%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E5%8F%AF%E4%B8%A2%EF%BC%8C%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20CHK%20--%3E%7C%22%E9%94%99%22%7C%20REST%5B%22%E6%81%A2%E5%A4%8D%E6%98%A0%E5%B0%84%20%2F%20GHR%22%5D%0A%20%20REST%20--%3E%20FLUSH%5B%22%E4%BD%9C%E5%BA%9F%E5%B9%B4%E8%BD%BB%20ROB%20%E9%A1%B9%22%5D%0A%20%20FLUSH%20--%3E%20REF%5B%22%E4%BB%8E%E6%AD%A3%E7%A1%AE%20PC%20%E9%87%8D%E5%8F%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("恢复延迟计入误预测损失拍：不只是「重新填满五级」，而是「重新填满 ROB 与发射队列」。这就是为何 "),E("a",{href:"/cs/gshare-predictor"},"gshare"),e(" 之后要把准确率抠得很紧——窗口越大，一次冲刷越贵。load 已经填了 cache 的行"),E("strong",null,"不会"),e("因冲刷而作废：那是微结构副作用，架构上允许；后课 Spectre 会把这点当成泄露面，本课只记「cache 不是 ROB 的一部分」。")],-1)),(r(),l(A,null,{default:t(()=>[B(o,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIDE%5B%22%E8%AF%AF%E9%A2%84%E6%B5%8B%E6%97%B6%E5%B7%B2%E5%8F%91%E7%94%9F%E7%9A%84%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%20--%3E%20REG%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%86%99%EF%BC%9A%E9%9A%8F%20ROB%20%E5%86%B2%E5%88%B7%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20SIDE%20--%3E%20MAP%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%E6%98%A0%E5%B0%84%EF%BC%9A%E4%BB%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E6%81%A2%E5%A4%8D%22%5D%0A%20%20SIDE%20--%3E%20LD%5B%22load%20%E5%A1%AB%E5%85%85%E7%9A%84%20cache%20%E8%A1%8C%EF%BC%9A%E4%B8%8D%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20LD%20--%3E%20WHY%5B%22%E6%9E%B6%E6%9E%84%E4%B8%8D%E8%A6%81%E6%B1%82%E5%9B%9E%E6%BB%9A%E5%BE%AE%E7%BB%93%E6%9E%84%E7%8A%B6%E6%80%81%22%5D%0A%20%20SIDE%20--%3E%20ST%5B%22store%EF%BC%9A%E6%8F%90%E4%BA%A4%E5%89%8D%E4%B8%8D%E8%AE%B8%E5%AF%B9%E5%A4%96%E5%8F%AF%E8%A7%81%22%5D%0A%20%20ST%20--%3E%20MESI%5B%22%E4%B8%8E%20MESI%20%E6%8F%90%E4%BA%A4%E6%89%8D%E5%8F%91%E4%BA%8B%E5%8A%A1%E4%B8%80%E8%87%B4%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p>这张图回答的是：一次误预测冲刷时各类副作用各自的归宿——哪些回滚、哪些从快照恢复、哪些（cache）根本不在回滚合同里、哪些（store）靠延迟到提交来绕开。</p><p>store 不得在提交前对别的核可见，否则无法恢复——与 <a href="/cs/mesi-protocol">MESI</a> 的「提交才发事务」一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入寄存器重命名的具体自由列表算法，那是下一课。也不处理内存序与 load 越过 store 的消歧，那是 LSQ 课。精确异常与误预测共用冲刷通道，但异常的 PC 与原因码要在 ROB 头递交，时机更严。</p><p>后课默认：推测 = 检查点 + 按预测执行；失败 = 恢复映射并冲刷年轻指令。WAR/WAW 仍要靠重命名才能在窗口里真正并行。</p><p><span class="marginnote">常见误区：初学者容易以为冲刷会「清掉一切」。寄存器、映射、队列都会回滚，唯独 load 已填进 cache 的行不作废——cache 不是 ROB 的一部分。这个「漏网之鱼」正是后课 Spectre 的泄露面。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>误预测恢复与精确中断共用 ROB 冲刷；预测器与映射要有检查点。</li><li>cache 填充不会随冲刷回滚。</li><li>重命名如何提供可恢复的映射，是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Smith and Pleszkun, <em>ISCA</em>, 1985。</li></ul>',8))])}const f=n(c,[["render",d]]);export{S as __pageData,f as default};
